func TestRunRejectsCanceledContextBeforeLaunch(test *testing.T) {
	ctx, cancel := context.WithCancel(context.Background())
	cancel()
	runner := &Runner{Path: "this-command-must-not-start"}
	_, err := runner.Run(ctx, "account", "show")
	if !errors.Is(err, context.Canceled) {
		test.Fatalf("got %v, want context.Canceled", err)
	}
}

func TestRunPreservesProcessError(test *testing.T) {
	runner := helperRunner(test)
	_, err := runner.Run(context.Background(), "-test.run=^TestAzCLIProcessHelper$", "--", "fail")
	var exitError *exec.ExitError
	if !errors.As(err, &exitError) || exitError.ExitCode() != 23 {
		test.Fatalf("got %v, want exit code 23", err)
	}
	if !strings.Contains(err.Error(), "simulated CLI failure") {
		test.Fatalf("missing CLI diagnostic: %v", err)
	}
}

func TestRunBoundsInheritedOutputPipes(test *testing.T) {
	runner := helperRunner(test)
	ctx, cancel := context.WithTimeout(context.Background(), 15*time.Second)
	defer cancel()
	output, err := runner.Run(ctx, "-test.run=^TestAzCLIProcessHelper$", "--", "spawn")
	childID, parseErr := strconv.Atoi(strings.TrimSpace(string(output)))
	if parseErr != nil {
		test.Fatalf("helper child PID: %v (CLI error: %v)", parseErr, err)
	}
	child, findErr := os.FindProcess(childID)
	if findErr == nil {
		defer child.Release()
		defer child.Kill()
	}
	if !errors.Is(err, exec.ErrWaitDelay) {
		test.Fatalf("got %v, want bounded output-pipe wait", err)
	}
}

func helperRunner(test *testing.T) *Runner {
	test.Helper()
	executable, err := os.Executable()
	if err != nil {
		test.Fatal(err)
	}
	return &Runner{
		Path: executable,
		Env:  append(os.Environ(), "DDOS_AZCLI_TEST_HELPER=1"),
	}
}

func TestAzCLIProcessHelper(test *testing.T) {
	if os.Getenv("DDOS_AZCLI_TEST_HELPER") != "1" {
		return
	}
	switch os.Args[len(os.Args)-1] {
	case "fail":
		fmt.Fprintln(os.Stderr, "simulated CLI failure")
		os.Exit(23)
	case "spawn":
		child := exec.Command(os.Args[0], "-test.run=^TestAzCLIProcessHelper$", "--", "hold-output")
		child.Stdout = os.Stdout
		child.Stderr = os.Stderr
		if err := child.Start(); err != nil {
			test.Fatal(err)
		}
		fmt.Fprintln(os.Stdout, child.Process.Pid)
		child.Process.Release()
		os.Exit(0)
	case "hold-output":
		timer := time.NewTimer(time.Minute)
		defer timer.Stop()
		<-timer.C
		os.Exit(0)
	default:
		test.Fatal("unknown helper mode")
	}
}
